    'M': 8192,
    'N': 8192,
    's': 3.14,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    A = jax.random.uniform(key, (CONFIG['M'], CONFIG['N']), dtype=dtype)
    s = jnp.asarray(CONFIG['s'], dtype=dtype)
