        dtype,
    )
    return (x,)


def _project_to_hypersphere(v):
    v_norm = jnp.sum(v * v, axis=1, keepdims=True)
    a = 2 * v / (v_norm + 1)
    b = (v_norm - 1) / (v_norm + 1)
    return jnp.concatenate([a, b], axis=1)


