    pooled = _adaptive_avg_axis(x, CONFIG['out_h'], axis=1)
    pooled = _adaptive_avg_axis(pooled, CONFIG['out_w'], axis=2)  # (C, 7, 7)
    # squeeze is a no-op for C > 1
    out = jnp.transpose(pooled, (1, 2, 0))  # (7, 7, C)
    return out.reshape(-1, out.shape[-1])

